	self.getCurInfo = function( curcode ) {
		if ( curcode in curinfo )
			return curinfo[curcode];
		else
			return {
				"symbol"        : "?",
				"id"            : curcode.substr(0, 2),
				"rate_precision": 5,
				"country"       : "unknown",
				"name"          : curcode,
			};
	};

	self.init = function() {
		$.ajax({
			url      : data_url,
			method   : 'get',
			dataType : 'json',
		}).done(function( data ) {
			curinfo = _.mapObject(data, function( cur ) {
				// localize the keys first
				_.assign(cur, cur[DVL.lang]);
				delete cur['en'];
				delete cur['fr'];
				return cur;
			});
			loadInitData();
		});
	}

	var loadInitData = function( done_func ) {
		var pending = 2;

		self.rateCall(
			{ 'do': 'updated' },
			function( data ) {
				self.rates.updated = I18N.formatDate(data.updated);
				_postcalls();
			},
			true
		);

		self.rateCall(
			{ 'do': 'currencies' },
			function( data ) {
				self.currencies = data;
				_postcalls();
			},
			true
		);

		function _postcalls() {
			if ( --pending === 0 ) {
				self.viewmodel.updated(APP.rates.updated);
				self.viewmodel.options.buy(_sortCurrs(APP.currencies.buy));
				self.viewmodel.options.sell(_sortCurrs(APP.currencies.sell));
				self.viewmodel.buy_currency('CAD');
				self.viewmodel.sell_currency('USD');
				self.viewmodel.applySubscriptions();
				self.viewmodel.listen_change(true);
				self.viewmodel.doConvert(true);
				ko.applyBindings(self.viewmodel);
				self.viewmodel.initCurrencyLists();
				$('#page-title').focus();
				$('body').scrollTop(0);
			}

			function _sortCurrs( currencies ) {
				// sort by currencies name (instead of code)
				currencies.sort(function( curr1, curr2 ) {
					return APP.getCurInfo(curr1).name.localeCompare(APP.getCurInfo(curr2).name);
				});

				// put these at the front of the list
				// currencies.unshift('SPACER');
				_.each(['CHF','JPY','MXN','AUD','GBP','EUR','USD','CAD'], function( curr ) {
					if ( _.contains(currencies, curr) ) {
						currencies = _.without(currencies, curr);
						currencies.unshift(curr);
					}
				});
				return currencies;
			}
		}
	};

	/**
	 * callback function has the source type of the conversion bound to it
	 */
	self.convert = function( from_curr, to_curr, trade, amount, callback ) {
		//DEBUG(trade +' '+ amount +' '+ from_curr +' to '+ to_curr);
		if ( amount <= 0 ) {
			callback({"amount":"0","status":"success","frate":1,"trate":1});
		} else {
			self.rateCall(
				{
					'do'    : 'conv',
					'from'  : from_curr,
					'to'    : to_curr,
					'trade' : trade,
					'amount': amount
				},
				callback,
				false
			);
		}
	};

	return self;
})();

