var Tracking = (function(){
	var self = {
		"enabled" : true,
	};

	// events that are commented out are handled by tag attributes on page
	var _events = {
		"search_atm"      : {"action": "button click", "label": "locate a branch or atm - search - atm selection"},
		"search_branch"   : {"action": "button click", "label": "locate a branch or atm - search - branch selection"},
		"calculate"       : {"action": "calculate", "label": ""},
		"error"           : {"action": "error", "label": "[Error Message Title]"},
		// "faq_question"    : {"action": "click", "label": "FAQ: [question]"},
		// "switch_currency" : {"action": "button click", "label": "switch currency button"},
		// "faq"             : {"action": "click", "label": "FAQ tab"},
	};

	self.event = function( name, arr ) {
		if ( !(name in _events) )
			return;
		console.debug("tracking event: "+ name, arr);
		
		var action = _events[name].action; // tracking event
		var label = "";
		var value = "";
		switch ( name ) {
		case "calculate":
			label = "currency i have: "+ arr[0] +"- currency I want: "+ arr[1];
			value = arr[2];
			break;

		case "error":
			label = arr[0];
			break;

		default:
			label = _events[name].label;
			break;
		}

		_fire_event(action, label, value);
	};

	var _fire_event = function( action, label, value ) {
		dataLayer.push({
			'event': 'ga-event',
			'ga-event': {
				'category': 'deposits fx calculator',
				'action'  : action,
				'label'   : label,
				'value'   : value
			}
		});
	}

	return self;
})();

